-- Lesson 1.4 study workbook release; source from Six-Week Master v2.0.
-- Does not release lesson early or modify existing workbook answers.
update public.aca_phase_two_workbook_definitions
set content=jsonb_set(content,'{pages}',coalesce(content->'pages','[]'::jsonb)||'{"number":4,"lesson_id":"1.4","kicker":"JOURNEY ONE / LESSON 1.4","title":"Direct Professional Requests and Decision Support","blocks":[{"type":"heading","text":"What a professional request must contain"},{"type":"text","text":"A well-formed AI request names purpose, audience, context, task, constraints and quality. These are six decisions a responsible person makes before delegating support to a model. The AI tool may assist with organization, comparisons and drafting; it does not possess approval authority."},{"type":"note","title":"The Professional Request Framework","text":"PURPOSE: the result the work should serve. AUDIENCE: who needs the result. CONTEXT: relevant verified facts and limitations. TASK: the work being requested. CONSTRAINTS: privacy, permissions and what is prohibited. QUALITY: what counts as a dependable outcome.","theme":"gold"},{"type":"field","id":"p2-j1-4-original","label":"Record your first, unrefined request to your AI assistant.","hint":"Keep it for comparison after revision.","lines":4},{"type":"field","id":"p2-j1-4-purpose","label":"Purpose — why is this result needed?","hint":"","lines":4},{"type":"field","id":"p2-j1-4-audience","label":"Audience — who will use the work?","hint":"","lines":4},{"type":"field","id":"p2-j1-4-context","label":"Context — what source-backed information from your ongoing project matters?","hint":"Carry forward the audience need and value hypothesis from Lessons 1.2 and 1.3.","lines":4},{"type":"field","id":"p2-j1-4-task","label":"Task — what specific output do you want the AI to prepare?","hint":"","lines":4},{"type":"field","id":"p2-j1-4-constraints","label":"Constraints — privacy, budget, permissions, unverified data or prohibited commitments.","hint":"","lines":4},{"type":"field","id":"p2-j1-4-quality","label":"Quality — how will the work be verified and judged useful?","hint":"","lines":4},{"type":"heading","text":"A fictional founder''s unsupported recommendation"},{"type":"text","text":"A founder considers two customer-service offerings: a simple approved reference guide and an AI response assistant. The founder does not yet have verified customer demand, delivery capacity or actual costs. An AI response that selects a winner and promises financial returns is not evidence. A responsible comparison asks what remains missing and keeps claims labeled."},{"type":"note","title":"Fictional teaching case","text":"Option A — approved reference guide. Option B — AI response assistant. Customer preference, delivery capacity and costs are NOT established. This is a training case, not real market research.","theme":"gold"},{"type":"field","id":"p2-j1-4-a","label":"Describe Option A for your own project. What evidence supports or limits it?","hint":"","lines":4},{"type":"field","id":"p2-j1-4-b","label":"Describe Option B. What constraints or human reviews would it require?","hint":"","lines":4},{"type":"heading","text":"Ask AI to compare — then verify"},{"type":"text","text":"Open your chosen AI assistant on your phone, tablet or computer. Enter only appropriately sanitized information. Improve your initial request using the six framework elements, then copy the model-neutral comparison request below."},{"type":"note","title":"Approved AI request","text":"Compare options A and B using this purpose, audience, context, constraints and quality standard. Separate supplied evidence, assumptions and unknowns. Ask necessary questions before recommending. Inputs: [sanitized brief].","theme":"gold"},{"type":"field","id":"p2-j1-4-improved","label":"Record your improved six-element request.","hint":"Keep both the original and improved requests.","lines":4},{"type":"field","id":"p2-j1-4-comparison","label":"What evidence, tradeoffs, alternatives and uncertainties did AI identify?","hint":"Separate supplied facts from suggestions.","lines":4},{"type":"field","id":"p2-j1-4-challenge","label":"Identify one important unsupported claim or assumption.","hint":"","lines":4},{"type":"field","id":"p2-j1-4-source","label":"What authorized document, observation or conversation could verify it?","hint":"If you cannot verify it, mark it unresolved rather than accepting the claim.","lines":4},{"type":"field","id":"p2-j1-4-followup","label":"Record the clarifying follow-up you asked AI.","hint":"Ask about a concrete gap, not merely to make the answer longer.","lines":4},{"type":"field","id":"p2-j1-4-improvement","label":"How did the follow-up actually improve the decision?","hint":"","lines":4},{"type":"heading","text":"Record a human decision memo"},{"type":"text","text":"A professional decision memo includes alternatives, supplied evidence, tradeoffs, uncertainty, accountable decision owner and an approved or provisional next step. The final decision belongs to the authorized person, not the model."},{"type":"field","id":"p2-j1-4-memo","label":"Write your decision memo.","hint":"State which recommendation remains provisional or unverified.","lines":4},{"type":"field","id":"p2-j1-4-owner","label":"Who has authority to approve this decision or its real-world implementation?","hint":"","lines":4},{"type":"field","id":"p2-j1-4-check","label":"Which missing input would make a recommendation unreliable, and why?","hint":"","lines":4},{"type":"note","title":"Carry the work forward","text":"Save the request comparison and decision memo in your continuing Project Record. The next lesson will scope a finishable project artifact. Your completed workbook notes remain available for independent review, printing or download, while unreleased sections stay locked.","theme":"gold"}]}'::jsonb,true),version=version+1,updated_at=now()
where journey_number=1 and not exists (select 1 from jsonb_array_elements(content->'pages') p where p->>'lesson_id'='1.4');
